sible{outline:3px solid #9ee6dc;outline-offset:1px;border-color:var(--brand)}button{width:auto;padding:9px 12px;border:0;border-radius:6px;background:var(--brand);color:white;font-weight:700;cursor:pointer}button:hover{background:var(--brand-dark)}button.secondary{background:#eef4f3;color:#0f5149}button.danger{background:#fff1f0;color:var(--danger);border:1px solid #f6c7c2}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.actions button{flex:1}.logout{padding:7px 10px;background:#eef4f3;color:#0f5149}.err,.ok{margin-top:10px;border-radius:6px;padding:9px 10px;font-size:14px}.err{color:var(--danger);background:var(--danger-bg);border:1px solid #f4c7c3}.ok{color:var(--ok);background:var(--ok-bg);border:1px solid #b7e4c7}.list-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.activity,.request-row,.auth-row,.split-share{display:grid;gap:5px;border-top:1px solid var(--line);padding:12px 0}.activity:first-child,.request-row:first-child,.auth-row:first-child{border-top:0}.row-head{display:flex;justify-content:space-between;gap:8px;align-items:center}.amount{font-weight:800}.muted{color:var(--muted)}.note{color:#344054}.empty{color:var(--muted);text-align:center;padding:20px}.auth-card{max-width:420px;margin:8vh auto}.page-heading{margin:0 0 14px}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media (max-width:980px){.grid{grid-template-columns:1fr 1fr}.grid .wallet{grid-column:1/-1}}@media (max-width:680px){.nav{align-items:flex-start;flex-wrap:wrap}.brand{width:100%}.spacer{display:none}.user{width:100%;justify-content:space-between}.wrap{padding:14px}.grid,.two-col{grid-template-columns:1fr}.actions button,.logout{flex:1 1 auto}.money{font-size:30px}}
