let token=localStorage.token||'',me=null,payDraft={to_handle:'',amount:'',note:'',visibility:'public'},paySig='',payKey='';const q=s=>document.querySelector(s);function fmt(v){let m=me?.minor_units??2,c=me?.currency||'EUR';return (m?(v/10**m).toFixed(m):String(v))+' '+c}function minor(s){let m=me?.minor_units??2;if(!/^\d+(\.\d+)?$/.test(s))throw Error('bad amount');let [a,b='']=s.split('.');if(b.length>m)throw Error('bad amount');return Number(a)*10**m+Number((b+'0'.repeat(m)).slice(0,m))}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function idem(x){return btoa(JSON.stringify(x)).replace(/[^a-z0-9]/gi,'').slice(0,40)||'k'}function field(label,test,value='',type='text',hint='',extra=''){return `<div class=field><label>${label}</label><input data-testid=${test} type=${type} value="${esc(value)}" ${extra}>${hint?`<div class=hint>${hint}</div>`:''}</div>`}function status(id,msg,ok=false){return `<div data-testid=${id} class=${ok?'ok':'err'}>${esc(msg)}</div>`}
async function api(p,o={}){o.headers={...(o.headers||{}),'Content-Type':'application/json'};if(token)o.headers.Authorization='Bearer '+token;let r=await fetch(p,o);if(r.status==204)return null;let j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error?.code||'error');return j}
async function boot(){if(token)try{me=await api('/me')}catch{token='';localStorage.removeItem('token')}render()}
function nav(){return `<div class=nav><div class=brand>Pocketful</div><a href="/">Wallet</a><a href="/requests">Requests</a><a href="/split">Split</a><a href="/authorizations">Holds</a><span class=spacer></span>${me?`<div class=user><span data-testid=current-user>${esc(me.display_name)}</span><span class=handle data-testid=current-handle>@${esc(me.handle)}</span><button class=logout data-testid=logout-button onclick="localStorage.removeItem('token');token='';me=null;render()">Logout</button></div>`:''}</div>`}
async function home(){let act=await api('/activity').catch(()=>({payments:[]}));return `<div class=grid><section class="card wallet"><div class=eyebrow>Available</div><div class=money data-testid=wallet-available data-amount="${me.available}">${fmt(me.available)}</div><div class=balance-row><span class=pill data-testid=wallet-balance data-amount="${me.balance}">Balance ${fmt(me.balance)}</span>${me.held?`<span class=pill data-testid=wallet-held data-amount="${me.held}">Held ${fmt(me.held)}</span>`:''}</div><div class=actions style="margin-top:14px"><button class=secondary data-testid=wallet-refresh onclick=boot()>Refresh</button></div></section><section class=card><div class=panel-title><h2>Pay</h2><span class=eyebrow>Send</span></div>${field('Recipient handle','pay-handle',payDraft.to_handle,'text','Example: alex')}${field(`Amount (${me.currency})`,'pay-amount',payDraft.amount,'text','Use major units, e.g. 12.50')}${field('Note','pay-note',payDraft.note)}<div class=field><label>Visibility</label><select data-testid=pay-visibility><option value=public ${payDraft.visibility=='public'?'selected':''}>Public</option><option value=private ${payDraft.visibility=='private'?'selected':''}>Private</option></select></div><button data-testid=pay-submit onclick=pay()>Pay</button><div id=paymsg></div></section><section class=card><div class=panel-title><h2>Request</h2><span class=eyebrow>Collect</span></div>${field('Payer handle','request-handle','','text','Who should pay you')}${field(`Amount (${me.currency})`,'request-amount','','text','Use major units')}${field('Note','request-note')}<button data-testid=request-submit onclick=req()>Request</button><div id=reqmsg></div></section><section class=card><div class=panel-title><h2>Hold</h2><span class=eyebrow>Authorize</span></div>${field('Recipient handle','authorize-handle','','text','Who may capture this hold')}${field(`Amount (${me.currency})`,'authorize-amount','','text','Use major units')}${field('Note','authorize-note')}<div class=field><label>Visibility</label><select data-testid=authorize-visibility><option value=public>Public</option><option value=private>Private</option></select></div><button data-testid=authorize-submit onclick=authz()>Authorize</button><div id=authmsg></div></section></div>${feed(act.payments)}`}
function feed(ps){return ps.length?`<section data-testid=activity-list class=card><div class=list-title><h2 class=page-heading>Activity</h2><span class=muted>${ps.length} shown</span></div>${ps.map(p=>`<div class=activity data-testid="activity-item-${p.payment_id}" data-visibility="${p.visibility}"><div class=row-head><span class=amount data-testid="activity-amount-${p.payment_id}">${fmt(p.amount)}</span><span class=pill>${p.visibility}</span></div><span data-testid="activity-parties-${p.payment_id}">${esc(p.from_handle)} to ${esc(p.to_handle)}</span><div class=note data-testid="activity-note-${p.payment_id}">${esc(p.note||'No note')}</div></div>`).join('')}</section>`:'<section data-testid=empty-activity class="card empty">No activity yet</section>'}
async function pay(){try{payDraft={to_handle:q('[data-testid=pay-handle]').value,amount:q('[data-testid=pay-amount]').value,note:q('[data-testid=pay-note]').value,visibility:q('[data-testid=pay-visibility]').value};let d={to_handle:payDraft.to_handle,amount:minor(payDraft.amount),note:payDraft.note,visibility:payDraft.visibility},sig=JSON.stringify(d);if(sig!=paySig){paySig=sig;payKey=idem(d)}await api('/payments',{method:'POST',headers:{'Idempotency-Key':payKey},body:sig});me=await api('/me');render()}catch(e){q('#paymsg').innerHTML=status('pay-error',e.message)}}
